const {
    get
} = require('axios');
const endpoints = ['blur', 'greyscale', 'invert', 'pixalate', 'posterize', 'sepia', 'beautiful', 'blood', 'bobross', 'brazzers',
    'gay', 'kackolantern', 'phvideo', 'prison', 'treasure', 'triggered', 'whatspokemon', 'rainbow'
];
const BASE_URL = "https://eclyssia-api.tk/api/v1/"

for (const endpoint of endpoints) {
    module.exports[endpoint] = async (url) => {
        const res = await get(`${BASE_URL}${endpoint}?url=${url}`, {
            responseType: "arraybuffer"
        });
        if (res.status !== 200) {
            throw new Error(res.response);
        };
        return res.data;
    };
};